.box {
  border: {
    style: solid;
    width: 2px;
    color: red;
  }
}

.text-box {
  font: {
    family: Helvetica;
    size: 14px;
    weight: bold;
  }
}

h1, h2 {
  a, span {
    color: blue;
  }
}

.article {
  text-decoration: {
    line: underline;
    style: wavy;
    color: red;
  }
}

.focus-ring {
  outline: 2px solid transparent {
    offset: 4px;
    color: blue;
  }
}

.card {
  transition: {
    property: transform, opacity;
    duration: 0.3s;
    timing-function: ease-in-out;
  }
}

.spinner {
  animation: {
    name: spin;
    duration: 1s;
    iteration-count: infinite;
  }
}
